SELECT Имена_станций.NAME, Имена_ОЭС.nameoes, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2011.YEAR, Станции2011.NUST, Станции2011.nr, Станции2011.E, Станции2011.EOTP, Станции2011.EURT, Станции2011.EUST, Станции2011.Q, Станции2011.TURT, Станции2011.TUST, Станции2011.B, Станции2011.GAZ, Доп_угли2011.gazpp, Станции2011.MAZUT, Станции2011.TORF, Станции2011.SLAN, Станции2011.PROCH, Станции2011.UGOL, Станции2011.DON, Станции2011.PODM, Станции2011.PECH, Доп_угли2011.intin, Доп_угли2011.vork, Станции2011.ARKT, Станции2011.KUZN, Станции2011.URAL, Доп_угли2011.sver, Доп_угли2011.chel, Доп_угли2011.kizel, Станции2011.BASHK, Станции2011.KAZAH, Станции2011.KARAG, Станции2011.KAN, Доп_угли2011.nazar, Доп_угли2011.ibor, Доп_угли2011.berez, Доп_угли2011.per, Станции2011.TUNG, Доп_угли2011.jer, Доп_угли2011.karab, Станции2011.IRKUT, Доп_угли2011.azey, Доп_угли2011.mug, Доп_угли2011.cher, Станции2011.HAK, Станции2011.TUV, Станции2011.BUR, Доп_угли2011.gusin, Доп_угли2011.tugn, Станции2011.CHIT, Доп_угли2011.har, Доп_угли2011.urt, Станции2011.YAKUT, Доп_угли2011.neru, Доп_угли2011.pyak, Станции2011.AMUR, Доп_угли2011.rai, Доп_угли2011.erk, Станции2011.URG, Станции2011.PRIM, Станции2011.LUCH, Станции2011.MAG, Станции2011.SAH, Станции2011.USHUM, Станции2011.QOTR, Станции2011.SNK, Станции2011.EWTP, Станции2011.NT, Станции2011.OBOR, Станции2011.VED, Станции2011.OBL, Станции2011.DEP, Станции2011.OES, Станции2011.ER, Станции2011.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2011.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип, Станции2011.KAMCH, Станции2011.CHUKOT, Доп_угли2011.irbei, Доп_угли2011.kansk, Доп_угли2011.okino, Доп_угли2011.tataur, Доп_угли2011.tarbag, Доп_угли2011.zab_kam, Доп_угли2011.bikin, Доп_угли2011.razdol, Доп_угли2011.hankai, Доп_угли2011.zyryan, Доп_угли2011.ekib, Доп_угли2011.maikub, Доп_угли2011.anad, Доп_угли2011.bering
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2011 LEFT JOIN Доп_угли2011 ON (Станции2011.NUMB1120=Доп_угли2011.NUMB1120) AND (Станции2011.YEAR=Доп_угли2011.YEAR)) ON Имена_ОЭС.oes=Станции2011.OES) ON Имена_областей.OBL=Станции2011.OBL) ON Имена_станций.NUMB=Станции2011.NUMB1120) LEFT JOIN имена_ГК ON Станции2011.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2011.BE=имена_БЕ.code;
